<?php
declare(strict_types=1);require __DIR__.'/bootstrap_saas.php';require_once __DIR__.'/passenger_auth_helpers.php';
$db=saas_db();if(isset($_GET['logout'])){passenger_logout();saas_redirect('passenger_auth.php');}$me=passenger_require_login();$profileId=(int)$me['passenger_profile_id'];
$q=$db->prepare("SELECT tp.id,tp.status,tp.fee,tp.discount,t.id tour_id,t.name,t.slug,t.start_date,t.end_date,COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.tour_passenger_id=tp.id AND p.tour_id=tp.tour_id),0) paid,COALESCE((SELECT SUM(f.total_price) FROM tour_passenger_features f WHERE f.tour_passenger_id=tp.id AND f.tour_id=tp.tour_id AND f.status='SELECTED'),0) feature_total,ti.id ticket_id,ti.ticket_number FROM tour_passengers tp JOIN tours t ON t.id=tp.tour_id LEFT JOIN ticket_instances ti ON ti.tour_passenger_id=tp.id AND ti.status='ISSUED' AND ti.voided_at IS NULL WHERE tp.passenger_profile_id=? AND tp.status<>'CANCELLED' AND t.organization_id=? ORDER BY t.start_date DESC,tp.id DESC");$q->execute([$profileId,(int)$me['organization_id']]);$tours=$q->fetchAll();
?><style>:root{--navy:#0B2A49;--gold:#F7AB17;--line:#e4e7ec}*{box-sizing:border-box}body{margin:0;background:#f5f8fc;color:#142033;font-family:Inter,system-ui,-apple-system,Segoe UI,Arial}.wrap{width:min(1050px,100%);margin:auto;padding:24px 16px 60px}.top{background:var(--navy);color:#fff;border-radius:22px;padding:24px;display:flex;justify-content:space-between;gap:20px;align-items:center;box-shadow:0 18px 45px #0b2a4920}.top h1{margin:0 0 5px;font-size:clamp(24px,4vw,34px)}.top a{color:#fff;text-decoration:none;margin-left:12px;font-weight:800;font-size:13px}.top .muted{color:#dbe5ef}.muted{color:#667085;font-size:13px}.card{background:#fff;border:1px solid var(--line);border-radius:20px;padding:22px;margin-top:18px;box-shadow:0 8px 30px #1018280a}.tour{border:1px solid var(--line);border-radius:16px;padding:18px;margin:12px 0}.tour-head{display:flex;justify-content:space-between;gap:10px}.pill{padding:5px 9px;border-radius:999px;background:#eef4fb;color:var(--navy);font-size:11px;font-weight:900}.actions{display:flex;flex-wrap:wrap;gap:8px}.actions a{padding:9px 12px;border-radius:9px;border:1px solid var(--line);text-decoration:none;font-size:12px;font-weight:850}.actions .primary{background:var(--navy);color:#fff;border-color:var(--navy)}.actions .ticket{background:var(--gold);color:#172033;border-color:var(--gold)}.money{font-weight:800}.due{color:#b42318}.paid{color:#067647}@media(max-width:650px){.top{display:block}.tour-head{display:block}.actions a{flex:1;text-align:center}}</style><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Tours</title><style>body{font-family:Arial,sans-serif;background:#f4f7fb;margin:0;color:#172033}.wrap{max-width:950px;margin:30px auto;padding:16px}.top,.card{background:#fff;border-radius:16px;padding:20px;margin-bottom:16px;box-shadow:0 6px 24px #0000000b}.top{display:flex;justify-content:space-between;gap:15px;align-items:center}.muted{color:#667085;font-size:13px}.tour{border:1px solid #eaecf0;border-radius:12px;padding:15px;margin:10px 0}.pill{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef2ff;font-size:12px;font-weight:700}.actions a{display:inline-block;margin:8px 8px 0 0;padding:8px 11px;border:1px solid #d0d5dd;border-radius:8px;text-decoration:none;color:#172033;font-size:13px}.actions .primary{background:#155eef;color:#fff;border-color:#155eef}.actions .ticket{background:#067647;color:#fff;border-color:#067647}.money{font-weight:700}.due{color:#b42318}.paid{color:#067647}@media(max-width:650px){.top{display:block}}</style></head><body><main class="wrap"><section class="top"><div><h1>Welcome, <?=saas_h($me['full_name'])?></h1><div class="muted"><?=saas_h($me['email']??'')?> · <?=saas_h($me['phone']??'')?></div></div><div><a href="passenger_profile.php">My Profile</a> · <a href="passenger_dashboard.php?logout=1">Log out</a></div></section><section class="card"><h2>My Tours</h2><?php if(!$tours):?><p class="muted">No active tour bookings are linked to your account yet.</p><?php endif;?><?php foreach($tours as $t):$gross=max(0,(float)$t['fee']-(float)$t['discount']+(float)$t['feature_total']);$due=max(0,$gross-(float)$t['paid']);?><div class="tour"><strong><?=saas_h($t['name'])?></strong> <span class="pill"><?=saas_h($t['status'])?></span><div class="muted"><?=saas_h((string)$t['start_date'])?><?=($t['end_date']?' → '.saas_h((string)$t['end_date']):'')?></div><p class="money">Total: <?=number_format($gross,2)?> · Paid: <span class="paid"><?=number_format((float)$t['paid'],2)?></span> · Due: <span class="<?=($due>0?'due':'paid')?>"><?=number_format($due,2)?></span></p><div class="actions"><a class="primary" href="public_booking.php?tour_id=<?=$t['tour_id']?>&account=1">Manage Booking</a><a href="public_seat_select.php?tour_id=<?=$t['tour_id']?>&account=1">Seat</a><a href="public_room_select.php?tour_id=<?=$t['tour_id']?>&account=1">Room</a><?php if($due>0):?><a href="public_checkout.php?tour_id=<?=$t['tour_id']?>&account=1">Payment</a><?php endif;?><?php if($t['ticket_id']):?><a class="ticket" href="passenger_ticket.php?ticket_id=<?=$t['ticket_id']?>">Ticket · <?=saas_h($t['ticket_number'])?></a><?php endif;?></div></div><?php endforeach;?></section></main></body></html>